import React, { useState, useEffect } from 'react';

const Dashboard = () => {
  const [rotation, setRotation] = useState({ x: -10, y: 30 });

  const handleMouseMove = (e) => {
    const { innerWidth, innerHeight } = window;
    // حساب الدوران بناءً على حركة الماوس
    const x = (e.clientY / innerHeight - 0.5) * 20; // دوران حول محور X
    const y = (e.clientX / innerWidth - 0.5) * 40;  // دوران حول محور Y
    setRotation({ x: -10 - x, y: 30 + y });
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div className="container-fluid p-0 overflow-hidden" style={{ minHeight: '80vh' }}>
      <div className="row g-0 align-items-center" style={{ minHeight: '80vh' }}>
        
        {/* القسم النصي */}
        <div className="col-lg-6 p-5 fade-in">
          <div className="p-lg-5">
            <h1 className="display-3 fw-bold mb-4" style={{ background: 'linear-gradient(45deg, #667eea, #764ba2)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
              مستقبل العقارات <br/> بين يديك
            </h1>
            <p className="lead text-muted mb-5" style={{ lineHeight: '1.8' }}>
              منصة <strong>سمسار برو</strong> هي الحل الأمثل لإدارة وتسويق العقارات بذكاء. 
              نجمع بين التكنولوجيا الحديثة وسهولة الاستخدام لنوفر لك تجربة فريدة في البحث عن منزل أحلامك أو إدارة استثماراتك العقارية.
            </p>
            
            <div className="d-flex gap-3">
              <button className="btn btn-primary btn-lg px-4 rounded-pill shadow-lg" onClick={() => document.querySelector('button[title="العقارات"]')?.click()}>
                تصفح العقارات
              </button>
              <button className="btn btn-outline-secondary btn-lg px-4 rounded-pill" onClick={() => document.querySelector('button[title="تواصل معنا"]')?.click()}>
                تواصل معنا
              </button>
            </div>

            <div className="mt-5 pt-4 border-top">
              <div className="row text-center">
                <div className="col">
                  <h3 className="fw-bold text-primary">+500</h3>
                  <small className="text-muted">عقار متاح</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-primary">+100</h3>
                  <small className="text-muted">عميل سعيد</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-primary">24/7</h3>
                  <small className="text-muted">دعم فني</small>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* القسم التفاعلي 3D */}
        <div className="col-lg-6 d-flex justify-content-center align-items-center" style={{ height: '60vh', perspective: '1000px' }}>
          <div 
            className="house-3d"
            style={{
              position: 'relative',
              width: '200px',
              height: '200px',
              transformStyle: 'preserve-3d',
              transform: `rotateX(${rotation.x}deg) rotateY(${rotation.y}deg)`,
              transition: 'transform 0.1s ease-out'
            }}
          >
            {/* Base */}
            <div className="face front" style={{...faceStyle, transform: 'translateZ(100px)'}}>🏠</div>
            <div className="face back" style={{...faceStyle, transform: 'rotateY(180deg) translateZ(100px)'}}>🚪</div>
            <div className="face right" style={{...faceStyle, transform: 'rotateY(90deg) translateZ(100px)'}}>🪟</div>
            <div className="face left" style={{...faceStyle, transform: 'rotateY(-90deg) translateZ(100px)'}}>🪟</div>
            <div className="face top" style={{...faceStyle, background: '#555', transform: 'rotateX(90deg) translateZ(100px)'}}></div>
            <div className="face bottom" style={{...faceStyle, background: '#333', transform: 'rotateX(-90deg) translateZ(100px)', boxShadow: '0 0 50px rgba(0,0,0,0.5)'}}></div>
            
            {/* Roof (Pyramid-ish using borders) */}
            <div className="roof" style={{
              position: 'absolute',
              top: '-100px',
              left: '0',
              width: '0',
              height: '0',
              borderLeft: '100px solid transparent',
              borderRight: '100px solid transparent',
              borderBottom: '100px solid #d35400',
              transform: 'rotateX(0deg) translateZ(0px) translateY(0px) translateX(0px)', // Simplified roof for CSS
              transformStyle: 'preserve-3d'
            }}>
               {/* CSS 3D Roof is complex, using a simple triangle representation for the front view */}
            </div>
          </div>
        </div>
      </div>

      <style>{`
        .face {
          position: absolute;
          width: 200px;
          height: 200px;
          background: rgba(255, 255, 255, 0.9);
          border: 2px solid #eee;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 4rem;
          box-shadow: inset 0 0 20px rgba(0,0,0,0.1);
          backface-visibility: visible;
        }
        .house-3d {
          animation: float 6s ease-in-out infinite;
        }
        @keyframes float {
          0%, 100% { transform: rotateX(-10deg) rotateY(30deg) translateY(0); }
          50% { transform: rotateX(-10deg) rotateY(30deg) translateY(-20px); }
        }
      `}</style>
    </div>
  );
};

const faceStyle = {
  position: 'absolute',
  width: '200px',
  height: '200px',
  background: 'linear-gradient(to bottom, #fff, #f0f0f0)',
  border: '1px solid #ccc',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  fontSize: '50px',
  userSelect: 'none'
};

export default Dashboard;
